ata/calendar/items/0/dtStart} }}","styles":{"width":42,"height":18,"fontSize":14,"fontWeight":700,"fontColor":"#e5000000","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"next_title","component":"Text","content":"{{ ${/data/calendar/items/0/title} }}","styles":{"width":56,"height":18,"fontSize":14,"fontWeight":600,"fontColor":"#99000000","maxLines":1,"textOverflow":"none","textAlign":"start"}}]}}
